/// <summary>
/// TMSEngine move it in contract class
/// <c>METTMSEngineContract</c> Run the TMSEngine in batch for the given transferId
/// </summary>
[DataContract]
class METTMSEngineContract
{
    InventTransferId transferId;


}

Method.Source:
/// <summary>
/// Parameter method which holds values TransferId for which TMSEngine needs to be executed
/// </summary>
/// <param name = "_transferId">MET TransferId</param>
/// <returns>TransferId</returns>
[DataContractAttribute]
public InventTransferId parmTransferId(InventTransferId _transferId = transferId)
{
    transferId = _transferId;
    return transferId;
}
